import os
import tkinter as tk

from tkinter import ttk
from PIL import Image, ImageTk
from pathlib import Path
from tkinter import filedialog

from ..widgets.widgets import AutocompleteCombobox, Tooltip, TextScrollCombo
from ..utils.logger import logger


class HeaderWidgetsSection(ttk.Frame):

    def __init__(self, parent, model, *args, **kwargs):
        super().__init__(parent, name="header_frame", borderwidth=1.5, relief="ridge")
        self.model = model
        self.graphics = self.__get_graphics()
        self.generate_profile_setup_var = tk.BooleanVar()
        self._setup()

    def _setup(self):
        select_profile_combobox = AutocompleteCombobox(self, values=self.model.available_profiles,
                                                       width=33,
                                                       prompt_text="Select TL profile",
                                                       name="select_profile_combobox")
        select_profile_combobox.grid(column=0, row=0, padx=(10, 0), pady=7)

        select_enb_build_combobox = AutocompleteCombobox(
            self, values=self.model.builds, width=33, prompt_text="Select eNB build", name="select_enb_build_combobox")
        select_enb_build_combobox.grid(column=0, row=1, padx=(10, 0), pady=7)
        select_enb_build_combobox.config(state="normal")
        select_dir_button = tk.Button(
            self, text="select_dir", image=self.graphics['folder_icon'], command=lambda: _update_path_label(self.model),
            name="select_dir_button", bg='#fafbfc',  activebackground='#fafbfc', borderwidth=0, highlightthickness=0)
        select_dir_button.grid(column=1, row=0, ipady=0, sticky=tk.W, ipadx=3, padx=8)

        output_path = ttk.Label(self, text="/home/ute/output_acg/config_files/", justify=tk.LEFT, wraplength=240, width=30, name='output_path')
        output_path.grid(column=2, row=0, sticky=tk.W, padx=11)
        output_path.grid_propagate(0)

        def _update_path_label(model):
            path = filedialog.askdirectory(initialdir="/home/ute/")
            output_path.config(text=path)

        checkbox_n_1 = ttk.Checkbutton(
            self, onvalue=True, offvalue=False, variable=self.generate_profile_setup_var, command=lambda: self.on_checkbutton_clicked(),
            text="     Enable custom config", name="allow_specific_cfg_checkbox"
        )
        Tooltip(checkbox_n_1, text='Enable config without locked CUS ports. (Advanced option for custom TEST LINES)')
        # checkbox_n_1.grid(column=1, row=1, sticky=tk.W, padx=8, columnspan=2)
        self.generate_profile_setup_var.set(False)
        checkbox_n_1.config(state='disabled')  # initially disabled; select TL profile at first
        self.message = TextScrollCombo(self,  text="Validation log", height=110, width=650, bg="white")

        validate_config_button = tk.Button(
            self, text="Validate Config", command=lambda: self.on_validate_config(), name="validate_config_button",
            relief="raised", bg="#00B1CC", width=16, height=1)
        validate_config_button.grid(column=4, row=0, padx=(8, 4), sticky="e", ipady=8)
        validate_config_button.grid_propagate(0)

        generate_config_button = tk.Button(
            self, text="Generate Config!", command=lambda: self.on_generate_config(), name="generate_config_button",
            relief="raised", bg="#00A0B5", width=16, height=1)
        Tooltip(generate_config_button, text='Generate Config Files. If locked, validation needs to be performed')
        generate_config_button.grid(column=4, row=1, padx=(8, 4), sticky="e", ipady=8)
        generate_config_button.grid_propagate(0)
        generate_config_button.config(state='disabled')

    def get_output_path(self):
        if self.children['output_path']['text']:
            return self.children['output_path']['text']
        else:
            return '/home/ute/auto_config_test'

    def on_generate_config(self):
        self.event_generate('<<GenerateConfig>>')

    def on_validate_config(self):
        self.event_generate('<<ValidateConfig>>')

    def on_checkbutton_clicked(self):
        state = "enabled" if self.generate_profile_setup_var.get() else "disabled"
        logger.info(f"Custom config {state}")
        self.event_generate('<<EnableCustomCButtonChanged>>')

    def disable_custom_config_after_topology_is_selected(self):
        self.generate_profile_setup_var.set(False)
        # self.on_checkbutton_clicked()  # simulate clicking fix double-time selection

    def enable_custom_config_checkbutton_after_first_topology_is_selected(self):
        self.children['allow_specific_cfg_checkbox'].config(state='normal')

    def lock_validate_config(self, event=None):
        self.children['validate_config_button'].config(state='disabled')

    def unlock_validate_config(self):
        self.children['validate_config_button'].config(state='normal')

    def lock_generate_config(self, event=None):
        self.children['generate_config_button'].config(state='disabled')

    def unlock_generate_config(self):
        self.children['generate_config_button'].config(state='normal')

    def get_log_lines(self):
        log_lines = []
        if not self.children['select_enb_build_combobox'].get().startswith('SBTS'):
            log_lines += ['No enb build selected!']
        return log_lines

    def __get_graphics(self):
        graphic_src_path = Path(os.path.abspath(__file__)).parents[1] / "graphics"

        folder_icon_resized = Image.open(graphic_src_path / "folder.png").resize((20, 20))

        folder_icon = ImageTk.PhotoImage(folder_icon_resized, master=self)

        return {'folder_icon': folder_icon}
